\label{lem:Fq}
Let $\mathbb{F}_q$ be a finite field of order $q$ and
let $X\subset \operatorname{\mathbb{P}}^{N}$ be a geometrically integral cubic hypersurface defined over $\mathbb{F}_q$,
where $N\geqslant 2$.
If $\sigma=\dim \operatorname{Sing}(X)\in \{-1,\dots,N-2\}$, where $\operatorname{Sing}(X)$ is the singular locus of $X$, then
\begin{equation*}
\#X(\mathbb{F}_q)-\frac{q^N-1}{q-1}
\ll_N q^{(N+\sigma)/2}.
\end{equation*}
Moreover,
$$
\#X(\mathbb{F}_q)-\frac{q^N-1}{q-1}\ll_N
\begin{cases}
q^{N-2} & \text{ if $N\geqslant 3$ and $X$ is not a cone,}\\
q^{N-3/2} &\text{ otherwise.}
\end{cases}
$$

\label{LEM:basically-zippel}
Let $Y\subset\operatorname{\mathbb{A}}_\mathbb{Z}^N$ be a closed subscheme whose
generic fibre
has dimension $0\leqslant d\leqslant N$.
Let $m\geqslant1$ be an integer.
Let $\bm{b}\in\mathbb{Z}^N$,
$L\geqslant1$ and $\bm{v}_0\in\mathbb{R}^N$.
Then
\begin{equation*}
\#\{\bm{v}\in Y(\mathbb{Z}):|\bm{v}-\bm{v}_0|\leqslant L,\ 
\bm{v}\equiv\bm{b}\bmod m\}
\ll_Y (1+L/m)^d.
\end{equation*}

\label{lem:stratified-composite-sieve}
Let $Y_0,Y_1,\ldots,Y_s\subset\operatorname{\mathbb{A}}_\mathbb{Z}^N$ be closed subschemes
whose generic fibres have dimensions at most $d_0,d_1,\dots,d_s$,
respectively.
Suppose that
\[
 N\geqslant d_0\geqslant d_1\geqslant\cdots\geqslant d_s\geqslant0.
\]
Let $\mathcal U \subset Y_0(\mathbb{Z})$ and $0 \leqslant \alpha \leqslant d_0$.
Suppose that
uniformly over $\bm{v}_0\in \mathbb{R}^N$,
$L\geqslant 1$,
$\bm{a}\in\mathbb{Z}^N$
and integers $q\geqslant 1$,
\begin{equation}
\label{eq:stratified-progression-hypothesis}
\#\{\bm{v}\in \mathcal U:
|\bm{v}-\bm{v}_0|\leqslant L,\;
\bm{v}\equiv\bm{a}\bmod q\}
\ll_{\mathcal U,\varepsilon}
(L+|\bm{v}_0|)^\varepsilon (1+L/q)^\alpha.
\end{equation}
Let $m\geqslant 1$ be an integer.
Let $\bm{b}\in\mathbb{Z}^N$,
$L\geqslant1$ and $\bm{v}_0\in\mathbb{R}^N$.
Let
$${\textstyle \mathcal C
:= \left\{\bm{v}\in \mathcal U \setminus \bigcup_{i=1}^s Y_i(\mathbb{Z}):
|\bm{v}-\bm{v}_0|\leqslant L,\;
\bm{v}\equiv\bm{b}\bmod m\right\}.}$$
For $R_1,\ldots,R_s \geqslant 1/2$, let
\[
\mathcal N(\bm R)
:= \sum_{\substack{q_i\sim R_i \\
\gcd(q_i,q_j)=1\ (i\ne j) \\ \gcd(q_i,m)=1}}
\sum_{\bm{v}\in\mathcal C}
\prod_{i=1}^s \mu^2(q_i)
\bm1_{\bm{v}\bmod q_i\in Y_i(\mathbb{Z}/q_i\mathbb{Z})}.
\]
Then
\begin{equation}\label{eq:stratified-composite-sieve}
\mathcal N(\bm R)
\ll_{\mathcal U,Y_0,\dots,Y_s,\alpha,\varepsilon}
(LR_1\cdots R_s + |\bm{v}_0|)^\varepsilon
\left(1
+ \frac{(L/m)^\alpha}{\prod_{i=1}^s R_i^{\alpha-d_i-1}}
+ \sum_{j=1}^s \frac{(L/m)^{d_j+1}}{\prod_{i=j+1}^s R_i^{d_j-d_i}}
\right),
\end{equation}
where empty products are interpreted as $1$.

The contribution to $\mathcal N(\bm R)$
from any individual vector $\bm{v}\in\mathcal C$
is $\ll (L+|\bm{v}_0|)^\varepsilon$,
by the divisor bound.
Thus \eqref{eq:stratified-composite-sieve} is trivial if $L \leqslant m$.
We may therefore assume $L>m$.

By the Lang--Weil bound,
we have $\#Y_i(\mathbb{F}_p) \ll p^{d_i}$ for all $p$.
If $R_1\cdots R_s\leqslant L/m$,
then there are $\ll \prod_i q_i^{d_i+\varepsilon}$
available residue classes $\bm{v}\bmod{q_1\cdots q_s}$.
Applying \eqref{eq:stratified-progression-hypothesis}
with $q = mq_1\cdots q_s \ll L$ gives
\begin{equation*}
\frac{\mathcal N(\bm R)}{(LR_1\cdots R_s + |\bm{v}_0|)^\varepsilon}
\ll \sum_{q_i\sim R_i}
(L/q)^\alpha
\prod_i q_i^{d_i}
\ll \frac{(L/m)^\alpha}{\prod_{i=1}^s R_i^{\alpha-d_i-1}},
\end{equation*}
which is satisfactory.
If $R_1\cdots R_s > L/m$, choose $1\leqslant j\leqslant s$ such that
\[
R_{j+1}\cdots R_s \ll L/m \ll R_jR_{j+1}\cdots R_s.
\]
This is possible because $R_1,\dots,R_s \gg 1$ and $1 \ll L/m \ll R_1\cdots R_s$.
Given $\bm{v}$, the number of available moduli $q_i$
is $\ll (L+|\bm{v}_0|)^\varepsilon$ for each $i<j$,
by the divisor bound.
On the other hand, there are $\ll \prod_{i>j} q_i^{d_i+\varepsilon}$
available residue classes $\bm{v}\bmod{\prod_{i>j} q_i}$.
Lemma~\ref{Le: StratGeoSieveStep1},
with $M := m\prod_{i>j} q_i \gg L/R_j$ in place of $m$,
with $Y := Y_j$ and with $S := R_j \gg 1 + L/M$, gives
\begin{equation*}
\frac{\mathcal N(\bm R)}{(LR_1\cdots R_s + |\bm{v}_0|)^\varepsilon}
\ll \sum_{q_i\sim R_i\ (i>j)} (1+L/M)^{d_j+1}
\prod_{i>j} q_i^{d_i}
\ll \sum_{q_i\sim R_i\ (i>j)} (L/M)^{d_j+1}
\prod_{i>j} q_i^{d_i}
\end{equation*}
since $L/M \gg 1$.
This is $\ll (L/m)^{d_j+1} \prod_{i>j} R_i^{d_i-d_j}$, which is satisfactory.

\label{defn : good}
We say that the cubic form $F$ is {\em good} if
for any $H \geqslant 1$ and any $\varepsilon>0$ we have the upper bound   
\[
\#\{\bm{z}\in\mathbb{Z}^n: |\bm{z}|\leqslant H,~ \operatorname{rank}(H(\bm{z}))=r\}
\ll_{F,\varepsilon} H^{r+\varepsilon},
\]
for each $0\leqslant r\leqslant n$,
where the implied constant only depends on $F$ and $\varepsilon$.

\label{LEM:my-guy-slop}
Assume $X(\mathbb{Q})=\emptyset$.
If $n\geqslant 2$, then $r(F) \geqslant 2 \lceil n/3 \rceil$.

\label{LEM:no-slop}
Assume that $X(\mathbb{Q})=\emptyset$.
Let $A\in\mathrm{GL}_n(\overline{\mathbb{Q}})$, and assign a real
weight $w_i$ to each variable $x_i$. The weight of a cubic monomial
$x_i x_j x_k$ is defined to be $w_i+w_j+w_k$. 
If every monomial occurring with a nonzero coefficient in
$F(A\bm{x})$ has nonnegative weight, then
\begin{equation}
\label{EQ:mean-weight}
w_1+\cdots+w_n\geqslant 0.
\end{equation}

\label{LEM:433-incidence-bound}
Assume $X(\mathbb{Q})=\emptyset$.
We have
\begin{align}
1 + \dim \operatorname{Sing} X \leqslant \max\{0, (2n-3)/3\},
\label{EQ:clean-slop-sing-bound} \\
\dim I\vert_{\operatorname{Sing}(\widehat X) \times \operatorname{\mathbb{A}}^n} \leqslant \max\{n, (4n-6)/3\},
\label{EQ:clean-slop-sing-incidence-bound} \\
\dim I \leqslant \max\{n, (4n-3)/3\}.
\label{EQ:clean-slop-incidence-bound}
\end{align}
Moreover, fix an integer $0\leqslant r\leqslant n$
and an irreducible closed subset $Z \subset X$,
whose affine cone $\widehat Z$ lies in $V_r$ but not in $V_{r-1}$.
If $Z \subset \operatorname{Sing} X$, then
\begin{equation}
\label{EQ:slop-sing-bound}
\dim \widehat Z \leqslant \min\{n-r,2r-3\}.
\end{equation}
If $Z \not\subset \operatorname{Sing} X$, then
\begin{equation}
\label{EQ:slop-smooth-bound}
\dim \widehat Z \leqslant \min\{r+(n-3)/3,2r-2\}.
\end{equation}

\label{PROP:rational-exceptional-hyperplanes-general}
Suppose $t\geqslant\max\{0,\dim\operatorname{Sing} X\}$,
and let $A_t$ be the Zariski closure of $B_t(\mathbb{Q})$ in $\operatorname{\mathbb{P}}^{n-1}$.
Then $A_t$ is defined over $\mathbb{Q}$.
Moreover, $A_t(\mathbb{Q})=B_t(\mathbb{Q})$ and
\begin{equation}
\label{EQ:rational-terminal-bound}
1+\dim A_t\leqslant
\max\left\{0,n-\left\lceil\frac{3(t+2)}2\right\rceil\right\}.
\end{equation}

\label{PROP:geometric-exceptional-hyperplanes-general}
If $t\geqslant (n+1)/3$, then
\begin{equation}
1+\dim W_t\leqslant\max\{0,n-t-2\}.
\label{EQ:geometric-gauss-bound}
\end{equation}
If $t\geqslant \max\{(n+1)/3,\dim\operatorname{Sing} X\}$, then
\begin{equation}
1+\dim B_t\leqslant\max\{0,n-t-2\}.
\label{EQ:geometric-terminal-bound}
\end{equation}

\label{COR:general-n-exceptional-hyperplanes}
Assume $n\geqslant10$ and $X(\mathbb{Q})=\emptyset$.
Then
\begin{equation}
\label{eq:n10-sing-X}
\dim\operatorname{Sing}(X)\leqslant \lfloor(2n-6)/3\rfloor \leqslant n-6.
\end{equation}
The set $B_{n-6}(\mathbb{Q})$ is finite if $n=10$,
and is empty if $n\geqslant11$. Moreover,
\begin{equation}\label{eq:rational-terminal-hyperplanes}
B_{n-5}(\mathbb{Q})=\emptyset.
\end{equation}
Geometrically, we have $B_{n-4} = \emptyset$ and
\begin{equation}\label{eq:terminal-hyperplane-dimensions}
1+\dim B_{n-6}\leqslant4,
\qquad
1+\dim B_{n-5}\leqslant3.
\end{equation}

\label{lem:geometry-all-hyperplane-sections}
There is a finite set of primes, depending only on $F$, such that for every
prime outside this set and every $\overline{\bm{v}}\neq\bm 0$, the cubic hypersurface
$Y_{\bm{v}}$
is geometrically integral.  Furthermore, if $Y_{\bm{v}}$ is a cone over $\overline{\mathbb{F}}_p$ with maximal vertex of 
projective dimension $s$, then
\begin{equation}
s\leqslant 1.
\label{eq:prime-sum-vertex-bound}
\end{equation}

\label{lem:prime-square-stratification}
Let $p$ be any prime and let $t\geqslant 0$.
If $p\nmid\bm{v}$ and $[\overline{\bm{v}}]\notin \mathcal W_{t,p}(\mathbb{F}_p)$,
then
\begin{equation}
\label{eq:p2-strat-bound}
S_{p^2}(\bm{v})\ll_F p^{n+t+1}.
\end{equation}
Moreover, for every prime $p$ and every $\bm{v}\in\mathbb{Z}^n$,
\begin{equation}
\label{eq:p2-cutoff}
S_{p^2}(\bm{v})\ll_F p^{2n-3}.
\end{equation}

\label{LEM:max-G-multiplicative}
The quantity $\mathcal G_{A,T}(\bm{y})$ is multiplicative in $T$.
That is,
\begin{equation}
\label{EQ:max-G-multiplicative}
\mathcal G_{A,T_1T_2}(\bm{y})
= \mathcal G_{A,T_1}(\bm{y})
\mathcal G_{A,T_2}(\bm{y})
\end{equation}
for all $A,T_1,T_2\geqslant 1$ with $\gcd(T_1,T_2)=1$.

\label{lem:q-flexible-lifting}
Let $A,T\geqslant 1$ and $q = A^2T$.
Then
\begin{equation}
\label{eq:q-flexible-pointwise}
|S_q(\bm{v})|
\leqslant A^{n+1} T
\sum_{a\in (\mathbb{Z}/A\mathbb{Z})^\ast}
\sum_{\substack{\bm{y}\bmod A\\F(\bm{y})\equiv0\bmod A
\\ a\nabla F(\bm{y})+\bm{v}\equiv \bm0\bmod A}} \mathcal G_{A,T}(\bm{y}).
\end{equation}

\label{Bernert-Smith-bound}
Let $r(\bm{a})$ be the rank of $H(\bm{a})$ over $\mathbb{Q}$.
Then $N_d(\bm{a}) \ll_F d^{n-r(\bm{a})} |\bm{a}|^{r(\bm{a})}$.

\label{LEM:square-and-diff}
If $A,T\geqslant 1$ are integers with $T\mid A$, then
\begin{equation*}
\mathcal G_{A,T}(\bm{a})
\leqslant T^{n/2} N_T(\bm{a})^{1/2}.
\end{equation*}

\label{lem:c/d-bound}
Let $c,d$ be positive integers such that $d$ is square-free and $d\mid c$.
Let $\bm{k}\in \mathbb{Z}^n$ such that $d\mid F(\bm{k})$. 
Then
$$
\#\left\{ \bm{x}\in (\mathbb{Z}/c\mathbb{Z})^n: 
\begin{array}{l}
\bm{x}\equiv \bm{k}\bmod{d}\\
F(\bm{x})\equiv 0\bmod{c}
\end{array}
\right\}\ll \left(\frac{c}{d}\right)^{n-1+\varepsilon} 
\gcd(d_2,\nabla F(\bm{k}))\gcd(d_2,\bm{k}),
$$
for any $\varepsilon>0$, where $d_2=d/d_1$ and $d_1$ is defined in \eqref{Defi:d1}.

\label{LEM:rank-two-root-lifting}
Suppose $p$ is odd.
Let $f_i\in \mathbb{Z}_p[\bm{y}]$ be homogeneous of degree $i$, for $0\leqslant i\leqslant 3$.
Suppose $\operatorname{rank}(f_2\bmod{p}) \geqslant 2$.
Let $g:=f_0+f_1+f_2+pf_3$.
Then, for every $s\geqslant0$,
\begin{equation}\label{eq:rank-two-root-lifting}
\#\{\bm y\bmod p^s:g(\bm y)\equiv0\bmod p^s\}
\leqslant (s+1)p^{s(n-1)}.
\end{equation}

\label{LEM:weighted-rank-locus}
If $0\leqslant \varrho\leqslant n$, then
$$\sum_{\substack{\bm u\in\mathbb{F}_p^n\\F(\bm u)=0\\
\operatorname{rank} H(\bm u) = \varrho}}
\gcd(p,\nabla F(\bm u))\gcd(p,\bm u)
\ll_F p^{\delta_n(\varrho) + \gamma_n(\varrho)}.$$

\label{lem:frog}
We have
\begin{equation}\label{eq:weighted-prime-smith-mass}
\sum_{\substack{\bm u\in\mathbb{F}_p^n\\F(\bm u)=0}}
N_p(\bm u)^{1/2}
\gcd(p,\nabla F(\bm u))\gcd(p,\bm u)
\ll_F p^{3n/2 - \lceil n/3\rceil - 1}.
\end{equation}

The first inequality is \eqref{eq:from-lemstar}.
On replacing the box radius by $V+r^{1/3}$,
the second inequality reduces to the claim
\[
 L_1(c,d,\mathcal V)
 \ll_{F,\varepsilon}r^{n/2+1+\varepsilon}d_1^{a_n}d_2^{b_n}V^n
 \qquad(V\geqslant r^{1/3}).
\]
We henceforth assume $V\geqslant r^{1/3}$.
If $c\leqslant V$, then $E_c(\mathcal V)\ll(V/c)^n$, and
Lemma~\ref{lem:cube-sum1} gives
\begin{align*}
L_1(c,d,\mathcal V)
&\ll_{F,\varepsilon}c^{n+1+\varepsilon}d^{n-\lceil n/3\rceil+1}V^n\\
&= r^{n/2+1}c^\varepsilon\frac dc\,d^{a_n}V^n
\leqslant r^{n/2+1+\varepsilon}d_1^{a_n}d_2^{b_n}V^n,
\end{align*}
since $d/c\leqslant 1$, $d=d_1d_2$, and $a_n\leqslant b_n$.
We may therefore assume $c>V$.

Two auxiliary results will be useful.
First, for integers $m\geqslant1$ and real $R\geqslant1$,
Lemma~\ref{Bernert-Smith-bound} and goodness
(Definition~\ref{defn : good}) give
\begin{equation}\label{eq:good-kernel-average}
\sum_{|\bm{h}|\leqslant R}N_m(\bm{h})^{1/2}
\ll_{F,\varepsilon}m^{n/2}R^\varepsilon \sum_{j=0}^n(R^3/m)^{j/2}
\ll_n R^\varepsilon m^{n/2}(1+R^3/m)^{n/2}.
\end{equation}
Second, 
on recalling the definition \eqref{eq:N_d}
of $N_p(\bm{u})$, it follows from combining 
the incidence bound \eqref{EQ:clean-slop-incidence-bound}
 with the Lang--Weil estimate, that
\begin{equation}\label{eq:laval_dim}
 \sum_{\bm{u}\in\mathbb{F}_p^n}N_p(\bm{u})
 \ll_F p^{n+\lfloor n/3\rfloor-1}.
\end{equation}

In the nonnegative sum \eqref{Eq: Defi.Lc,d,V}
defining $L_1(c,d,\mathcal V)$, we may weaken $c\mid F(\bm{a})$
to $d_1\mid F(\bm{a})$, and majorise the box $\bm{v}_0+[-V,V]^n$ by the
smooth weight function $e^n\exp(-\|\bm{v}-\bm{v}_0\|_2^2/V^2)$.
For $a\in(\mathbb{Z}/c\mathbb{Z})^\ast$, put
\[
 \sigma(\bm{h};a)=
 \sum_{\substack{\bm{a}\bmod c\\d_1\mid F(\bm{a})}}
 N_d(\bm{a})^{1/2}e_c(a\bm{h}\cdot\nabla F(\bm{a})).
\]
Poisson summation in the class
$\bm{v}\equiv-a\nabla F(\bm{a})\bmod c$ gives
\begin{equation}\label{eq:onion-poisson}
\begin{aligned}
 L_1(c,d,\mathcal V)
 &\ll_n c^{n+1}d^{n/2+1}(V/c)^n
\sum_{a \in (\mathbb{Z}/c\mathbb{Z})^*}\sum_{\bm{h}\in\mathbb{Z}^n}
 |\sigma(\bm{h};a)|
 \exp(-\pi^2\|\bm{h}\|_2^2V^2/c^2).
\end{aligned}
\end{equation}
Here the Fourier factor $e_c(\bm{h}\cdot\bm{v}_0)$ has absolute
value one, so all estimates remain uniform in $\bm{v}_0$.

Recall that $c=d_1c_2$, $\gcd(d_1,c_2)=1$, and $d_2^2\mid c_2$.
Write $\overline{c_2}$ for the inverse of $c_2$ modulo $d_1$,
and $\overline{d_1}$ for the inverse of $d_1$ modulo $c_2$.
The Chinese remainder theorem gives
\begin{align*}
 \sigma(\bm{h};a)
 =\left(
 \sum_{\substack{\bm{u}\bmod d_1\\d_1\mid F(\bm{u})}}
 N_{d_1}(\bm{u})^{1/2}
 e_{d_1}(a\overline{c_2}\bm{h}\cdot\nabla F(\bm{u}))
 \right)
\left(
 \sum_{\bm{u}\bmod c_2}N_{d_2}(\bm{u})^{1/2}
 e_{c_2}(a\overline{d_1}\bm{h}\cdot\nabla F(\bm{u}))
 \right).
\end{align*}
By Lemma~\ref{lem:frog}, with its gcd factors omitted, the first
factor is
\[
 \ll_{F,\varepsilon}d_1^{3n/2-\lceil n/3\rceil-1+\varepsilon}
 =d_1^{n+a_n+\varepsilon}.
\]
For the second factor, as in \cite[Eq.~(5.14)]{41} Cauchy's inequality over $\bm{u}\bmod d_2$,
followed by quadratic differencing, gives
\begin{align*}
\left|
 \sum_{\bm{u}\bmod c_2}N_{d_2}(\bm{u})^{1/2}
 e_{c_2}(a\overline{d_1}\bm{h}\cdot\nabla F(\bm{u}))
 \right|^2\leqslant
 \left(\sum_{\bm{b}\bmod d_2}N_{d_2}(\bm{b})\right)
 c_2^nN_{c_2/d_2}(\bm{h}).
\end{align*}
Since $d_2$ is square-free, combining the Chinese remainder theorem with \eqref{eq:laval_dim} gives
\[
 \sum_{\bm{b}\bmod d_2}N_{d_2}(\bm{b})
 \ll_{F,\varepsilon}d_2^{n+\lfloor n/3\rfloor-1+\varepsilon}.
\]
Combining the two factors, and using $c/d=(d_1c_2)/(d_1d_2)=c_2/d_2$, yields
\begin{equation}\label{eq:onion-sigma-refined}
\begin{aligned}
 |\sigma(\bm{h};a)|
 \ll_{F,\varepsilon}
 d_1^{n+a_n+\varepsilon}c_2^{n/2}
 d_2^{n/2+b_n+\varepsilon}N_{c/d}(\bm{h})^{1/2}
 =
 (cd)^{n/2}d^\varepsilon d_1^{a_n}d_2^{b_n}
 N_{c/d}(\bm{h})^{1/2}.
\end{aligned}
\end{equation}
In \eqref{eq:onion-poisson}, the contribution from
$|\bm{h}|\gg (c/V)\log(2c)$ is negligible by the trivial
bound for $\sigma(\bm{h};a)$.
In particular, substituting \eqref{eq:onion-sigma-refined} into \eqref{eq:onion-poisson} and applying \eqref{eq:good-kernel-average} with $m=c/d$ therefore gives
\begin{align*}
 L_1(c,d,\mathcal V)
 &\ll_{F,\varepsilon}
 c^{n/2+2+\varepsilon}d^{n+1}d_1^{a_n}d_2^{b_n}V^n
 \sum_{|\bm{h}|\ll(c/V)\log(2c)}N_{c/d}(\bm{h})^{1/2}\\
 &\ll_{F,\varepsilon}
 r^{n/2+1+\varepsilon}d_1^{a_n}d_2^{b_n}
 V^n(1+r/V^3)^{n/2}\\
 &\ll_{F,\varepsilon}
 r^{n/2+1+\varepsilon}d_1^{a_n}d_2^{b_n}V^n.
\end{align*}
In the last step we used $V\geqslant r^{1/3}$.
This proves the result.

\label{Le: Cubefull.finalbound}
For every $\varepsilon>0$, uniformly in $\bm{v}_0\in\mathbb{R}^n$, we have
\begin{equation}\label{eq:cubefull-average-sharp}
 \sum_{\substack{r\asymp R\\r\ \mathrm{cubefull}}}
 \sum_{\bm{v}\in\mathcal V}|S_r(\bm{v})|
 \ll_{F,\varepsilon}
 R^{n/2+1+\theta_n+\varepsilon}(V+R^{1/3})^n,
\end{equation}
where 
\begin{equation}\label{eq:powerfull-averaging-exponents}
 \theta_n=\max\left\{\frac25,\frac{n-2\lceil n/3\rceil}{6}\right\}.
\end{equation}
In particular, for $n=10$ the power of $R$ in this bound is
$32/5+\varepsilon$.

\label{lem:q-flexible-average}
Let $q = A^2T$, where $A,T\geqslant 1$.
Then
\begin{equation}
\sum_{\bm{a}\bmod{A}}
\max_{\substack{\bm{v}\bmod{q} \\ \bm{v}\equiv \bm{a}\bmod{A}}} |S_q(\bm{v})|
\leqslant
A^{n+2}T
\sum_{\substack{\bm{y}\bmod A\\F(\bm{y})\equiv0\bmod A}}
\mathcal G_{A,T}(\bm{y}),
\label{eq:q-flexible-average}
\end{equation}
where $\mathcal G_{A,T}(\bm{y})$ is defined in \eqref{eq:GAT-max-sum}.

\label{lem:q-easy-hessian-lift-bound}
For $a\geqslant 1$ and \(0\leqslant \varrho\leqslant n\),
\[
\#\{\bm{x}\bmod p^a:
F(\bm{x})\equiv0\bmod{p^a},\;
\operatorname{rank} H(\bm x\bmod p)=\varrho\}
\ll_{\varepsilon,F}
p^{(a-1)(n-1+\varepsilon)+\delta_n(\varrho)+\gamma_n(\varrho)\bm{1}_{a\geqslant 2}}.
\]

\label{q-translated-rank}
For every prime \(p\)
and matrix \(\mathcal T\in\operatorname{Mat}_{n\times n}(\mathbb{F}_p)\),
\begin{equation*}
\#\{\bm{y}\in\mathbb{F}_p^n:
\operatorname{rank}(\mathcal T+H(\bm{y}))\leqslant j\}
\ll_F p^{\tau_n(j)}.
\end{equation*}

\label{prop:q-smith-bound}
Let $q\geqslant 1$ be squarefull.
Suppose every prime $p\mid q$
is large enough in terms of $F$ and $\varepsilon$.
Choose \(1\leqslant a_p\leqslant\lfloor v_p(q)/2\rfloor\)
and let $t_p := v_p(q)-2a_p$.
If \(A := \prod_{p\mid q} p^{a_p}\)
and $T := \prod_{p\mid q} p^{t_p}$,
then the condition \eqref{EQ:radTA} holds and
\begin{equation}
\sum_{\bm{a}\bmod{A}}
\max_{\substack{\bm{v}\bmod{q} \\ \bm{v}\equiv \bm{a}\bmod{A}}} |S_q(\bm{v})|
\ll_{\varepsilon,F}
q^\varepsilon \prod_{p\mid q}p^{D_n(a_p,t_p)}.
\label{eq:q-global-smith-bound}
\end{equation}

\label{lem:q-smith-cubefull}
Assume $n=10$.
Let \(r\geqslant 1\) be cubefull.
Suppose every prime $p\mid r$
is large enough in terms of $F$ and $\varepsilon$.
Let
\begin{equation}
\label{eq:q-buw}
b := \prod_{v_p(r)>0} p^{\lfloor v_p(r)/3 \rfloor},
\qquad z_i := \prod_{\substack{v_p(r)>0 \\ v_p(r) \equiv i\bmod{3}}} p,
\end{equation}
for $0\leqslant i\leqslant 2$,
so that $r=b^3z_1z_2^2$ and $z_0z_1z_2\mid b$.
Define
\[
A := bz_2,\quad T := bz_1.
\]
Then \(r=A^2T\), the condition \eqref{EQ:radTA} holds, and
\begin{equation}
\sum_{\bm{a}\bmod{A}}
\max_{\substack{\bm{v}\bmod{r} \\ \bm{v}\equiv \bm{a}\bmod{A}}} |S_r(\bm{v})|
\ll_{F,\varepsilon}
r^{10+\varepsilon}z_0^{-2}z_1^{-4}z_2^{-1}.
\label{eq:q-route-zero}
\end{equation}

In view of Theorem~\ref{Bernert-n10-sing-series}
and Lemma~\ref{lem:restricted-multiplicative},
it suffices to show that for each $p\mid W$
the Euler factor $\sum_{k\geqslant 0} \operatorname{lcm}(p^k,p^{M_p})^{-n} S_{p^k,p^{M_p}}(\bm0)$
converges absolutely to a positive real number.
The absolute convergence itself is clear from Lemma~\ref{lem:restricted-multiplicative}
and \eqref{fixed-p-adic-stationary-phase}, since $r(F) \geqslant 2n/3 \geqslant 3$.
It remains to exhibit positivity.
First observe that if $j\geqslant M_p$ then
\begin{equation*}
\#\left\{\bm{x}\bmod p^j:
\bm{x}\in\Omega_p[j],\;F(\bm{x})\equiv0\bmod{p^j}\right\}
= \sum_{\substack{\bm{x}\bmod{p^j} \\ \bm{x}\bmod p^{M_p}\in\Omega_p[M_p]}}
p^{-j} \sum_{1\leqslant a\leqslant p^j} e_{p^j}(aF(\bm{x})).
\end{equation*}
Let $0\leqslant k\leqslant j$.
The total contribution to the right-hand side
from $a$ with $v_p(a) = j-k$ is
\begin{equation*}
\sum_{\substack{\bm{x}\bmod{p^j} \\ \bm{x}\bmod p^{M_p}\in\Omega_p[M_p]}}
p^{-j} \sum_{\substack{1\leqslant b\leqslant p^k \\ \gcd(b,p^k)=1}} e_{p^k}(bF(\bm{x}))
= p^{-j} p^{n(j-\max(k,M_p))} S_{p^k,p^{M_p}}(\bm0),
\end{equation*}
by counting lifts modulo $p^j$ of residues modulo
$p^{\max(k,M_p)}$.
It follows that
\begin{equation*}
\sum_{0\leqslant k\leqslant j} \operatorname{lcm}(p^k,p^{M_p})^{-n} S_{p^k,p^{M_p}}(\bm0)
= p^{-j(n-1)}
\#\left\{\bm{x}\bmod p^j:
\bm{x}\in\Omega_p[j],\;F(\bm{x})\equiv0\bmod{p^j}\right\}.
\end{equation*}
Taking $j\to \infty$ completes the proof,
in view of the lower bound \eqref{eq:localised-pos-density}.

\label{lem:q-fixed-shifted box}
Fix a prime $p$, and let
\(\Omega_p\) be the neighbourhood chosen in \eqref{eq:inel-Omega}.
Let $k \geqslant 0$ and $a := \lceil k/3 \rceil$.
Then
\begin{equation}
\sum_{\bm{a}\bmod{p^a}}
\max_{\substack{\bm{v}\bmod{p^{\max(k,M_p)}} \\ \bm{v}\equiv \bm{a}\bmod{p^a}}}
|S_{p^k,p^{M_p}}(\bm{v})|
\ll_{F,p}
p^{k(n + (4-r(F))/6)}.
\label{eq:q-fixed-shifted box}
\end{equation}

\label{n10:second-moment}
Let $L\subset\mathbb{Q}^n$ be a linear space of dimension $n-2$.
For every sufficiently large prime $p$, every $q=p^a$, and every
nontrivial $\psi_q$, one has
\begin{equation}
 \sum_{\bm{v}\in L(\mathbb{F}_q)}|T_q(\bm{v})|^2\ll_{F,L}q^{2n-3}.
 \label{n10:moment-two}
\end{equation}

\label{generic-irred}
Let $K=\overline{\mathbb{Q}}(T_3,\ldots,T_n)$.
Then $F(X_1,X_2,T_3,\dots,T_n)$ is irreducible in $\overline{K}[X_1,X_2]$.

Every positive cube-free integer $d$ can be written uniquely as
$d=d_1d_2^2$, where $d_1,d_2$ are coprime positive square-free
integers.
Suppose now that $\bm{v}\in P_j\cap Q_k\cap \mathbb{Z}^n$, so that necessarily
\begin{equation*}
0\leqslant j\leqslant k\leqslant n-4.
\end{equation*}
Then let
\begin{equation}\label{n10:K}
K(d,\bm{v})=
\prod_{\substack{p\mid d_1\\e(\bm{v};p)> j+2}}
p^{\frac{e(\bm{v};p)-j}{2}-1}
\prod_{\substack{p\mid d_2\\f(\bm{v};p)> k+2}}
p^{f(\bm{v};p)-k-2}.
\end{equation}
Moreover, for all integers $h\geqslant j+1$ and $\ell\geqslant k+1$ define the formal infinite products
\[
q_{\bm{v},h}=\prod_{\substack{p\\e(\bm{v};p)\geqslant h}}p,
\qquad
s_{\bm{v},\ell}=\prod_{\substack{p\\f(\bm{v};p)\geqslant \ell}}p,
\]
and let
\begin{equation}\label{n10:radicals}
R_{h,\ell}(d,\bm{v})
= \gcd(d_1,q_{\bm{v},h})
\gcd(d_2,s_{\bm{v},\ell}).
\end{equation}

\label{n10:Lemma-weight-gen}
Let $0\leqslant j,k\leqslant n-5$ and
$\bm{v}\in(P_j\cap Q_k)\cap\mathbb{Z}^n$.
If $D_1,D_2\geqslant 1/2$,
then for any two square-free integers $d_{1}\sim D_1$ and $d_2\sim D_2$
with $\gcd(d_{1},d_{2})=1$,
and for every $\varepsilon>0$, we have
\begin{equation}
\label{EQ:K-relaxed-hybrid-pointwise}
S_{d_{1}d_{2}^{2}}(\bm{v})
\ll_{F,\varepsilon} D^\varepsilon D_1^{\frac{n+j+3}{2}}D_2^{n+k+3} K(d_1d_2^2,\bm{v}),
\end{equation}
where $D = D_1D_2^2$.
In fact, if $K_j\geqslant 1/2$ then
\begin{equation}\label{n10:weighted-fixed-point}
\sideset{}{^*}\sum_{d_1\sim D_1}
\sideset{}{^*}\sum_{\substack{
d_2\sim D_2\\\gcd(d_1,d_2)=1
\\ K(d_1d_2^2,\bm{v})\sim K_j}}
|S_{d_1d_2^2}(\bm{v})|
\ll_{F,\varepsilon}
[D(2+|\bm{v}|)]^\varepsilon
D_1^{\frac{n+j+3}{2}}D_2^{n+k+3}
K_j,
\end{equation}
where every starred sum is restricted to square-free integers.
Moreover, if $j+1\leqslant h\leqslant n-3$ and $k+1\leqslant\ell\leqslant n-3$, then
\begin{equation}
\label{n10:residual-fixed-point}
\sideset{}{^*}\sum_{d_1\sim D_1}
\sideset{}{^*}\sum_{\substack{
d_2\sim D_2\\\gcd(d_1,d_2)=1
\\ R_{h,\ell}(d_1d_2^2,\bm{v}) = 1}}
|S_{d_1d_2^2}(\bm{v})|
\ll_{F,\varepsilon}
[D(2+|\bm{v}|)]^\varepsilon
D_1^{\frac{n+\max\{j+3,h\}}{2}}
D_2^{n + \max\{k+2,\ell\}}.
\end{equation}

In the notation of Propositions~\ref{PROP:Dante-partition-Pj}
and~\ref{PROP:partition-Qj}, we have
\[
\begin{aligned}
p\nmid\Delta(\bm{v})
&\quad\Longrightarrow\quad
S_p(\bm{v})\ll_F p^{\frac{n+j+1}{2}},\\
p\nmid\Theta(\bm{v})
&\quad\Longrightarrow\quad
S_{p^2}(\bm{v})\ll_F p^{n+k+1}.
\end{aligned}
\]
For $q=\gcd(d_1,q_{\bm{v},j+1},\Delta(\bm{v}))$
and $s=\gcd(d_2,s_{\bm{v},k+1},\Theta(\bm{v}))$,
multiplicativity
and the local bounds \eqref{EQ:modified-FK-condition} and \eqref{eq:square-benchmark}
give
\begin{equation}
\label{EQ:general-S-expansion}
S_{d_1d_2^2}(\bm{v})
\ll_{F,\varepsilon}
D^\varepsilon d_1^{\frac{n+j+1}{2}}d_2^{n+k+1}
\prod_{p\mid q}p^{(e(\bm{v};p)-j)/2}
\prod_{p\mid s}p^{f(\bm{v};p)-k}.
\end{equation}
Here the product of the local constants is absorbed into
$D^\varepsilon$. By the definition of $K$, we have
\[
\prod_{p\mid q}p^{(e(\bm{v};p)-j)/2}
\prod_{p\mid s}p^{f(\bm{v};p)-k}
\leqslant
K(qs^2,\bm{v})\,qs^2.
\]
To conclude the proof of \eqref{EQ:K-relaxed-hybrid-pointwise},
we observe that $qs^2 \leqslant d_1d_2^2$ and
$K(qs^2,\bm{v}) \leqslant K(d_1d_2^2,\bm{v})$,
since the exponents in the definition \eqref{n10:K} are positive.

For fixed $q,s$, there are
$O(D_1D_2/(qs))$ choices for $d_1,d_2$ satisfying
$q\mid d_1$ and $s\mid d_2$.
Consequently, the left-hand side of \eqref{n10:weighted-fixed-point} is
\[
\ll_{F,\varepsilon}
D^\varepsilon D_1^{\frac{n+j+1}{2}}D_2^{n+k+1}
\sum_{\substack{q\mid \gcd(q_{\bm{v},j+1},\Delta(\bm{v}))\\q\leqslant2D_1}}
\sum_{\substack{
s\mid \gcd(s_{\bm{v},k+1},\Theta(\bm{v}))\\s\leqslant2D_2\\\gcd(q,s)=1}}
K_j qs^2 \frac{D_1D_2}{qs}.
\]
Using $s\leqslant 2D_2$ and the divisor bound on the positive integers
$\Delta(\bm{v}),\Theta(\bm{v}) \ll (2+|\bm{v}|)^{O(1)}$,
the claim \eqref{n10:weighted-fixed-point} follows.

Finally, if $R_{h,\ell}(d_1d_2^2,\bm{v}) = 1$,
then $e(\bm{v};p)\leqslant h-1$ and $f(\bm{v};p)\leqslant \ell-1$
in the inequality \eqref{EQ:general-S-expansion},
so
\begin{equation*}
S_{d_1d_2^2}(\bm{v})
\ll_{F,\varepsilon}
D^\varepsilon d_1^{\frac{n+j+1}{2}}d_2^{n+k+1}
q^{(h-1-j)/2} s^{\ell-1-k}.
\end{equation*}
Proceeding as we did for \eqref{n10:weighted-fixed-point},
we find that the left-hand side of \eqref{n10:residual-fixed-point} is
\[
\ll_{F,\varepsilon}
D^\varepsilon D_1^{\frac{n+j+1}{2}}D_2^{n+k+1}
\sum_{\substack{q\mid \gcd(q_{\bm{v},j+1},\Delta(\bm{v}))\\q\leqslant2D_1}}
\sum_{\substack{
s\mid \gcd(s_{\bm{v},k+1},\Theta(\bm{v}))\\s\leqslant2D_2\\\gcd(q,s)=1}}
q^{(h-1-j)/2} s^{\ell-1-k} \frac{D_1D_2}{qs}.
\]
The divisor bound
yields
\eqref{n10:residual-fixed-point} on optimising over $q$ and $s$,
since $\frac{n+j+3}{2} + \max\{0,(h-3-j)/2\}
= \frac{n+\max\{j+3,h\}}{2}$
and $n+k+2 + \max\{0,\ell-2-k\}
= n + \max\{k+2,\ell\}$.

\label{LEM:n5divisorbound}
Let notation be as in \eqref{n10:average-box}.
For every $\varepsilon>0$,
\[
\sum_{\substack{
d\sim D\\d\ \mathrm{cube\text{-}free}\\
\gcd(d,m)=1}}
\sum_{\substack{
\bm{v}\in(P_{n-5}\cap Q_{n-5})\cap\mathcal V}}
|S_d(\bm{v})|\ll_{F,\varepsilon} (DH)^\varepsilon D^{n-1}T.
\]

\label{n10:weighted-conductor}
Let notation be as in \eqref{n10:average-box}.
Suppose $0\leqslant j\leqslant n-6$ and $k\in \{j,j+1\}$.
For every $K_j\geqslant 1/2$ and $\varepsilon>0$,
\begin{equation}\label{n10:weighted-mean}
\sum_{\substack{
d\sim D\\d\ \mathrm{cube\text{-}free}\\
\gcd(d,m)=1}}
\sum_{\substack{
\bm{v}\in(P_j\cap Q_k)\cap\mathcal V\\
R_{j+2,k+2}(d,\bm{v})\leqslant T\\
K(d,\bm{v}) \sim K_j}}
|S_d(\bm{v})|
\ll_{F,\varepsilon}
(DH)^\varepsilon T^{\theta_n(j,k)}D^{\frac{n+j+3}{2}}
K_j^{-\alpha_n\delta_0(j,k)},
\end{equation}
where $\theta_n(j,k) = n-j-1+\delta_0(j,k)-\delta_{n-7,n-6}(j)$
and $\alpha_n = 1/(n-8)$.

Let
\[
 r=R_{j+2,k+2}(d,\bm{v}),\qquad c=\gcd(d,r^2),\qquad b=d/c.
\]
Then $\operatorname{rad}(c)=r\leqslant T$, $\gcd(b,c)=1$, $R_{j+2,k+2}(b,\bm{v})=1$,
and $K(b,\bm{v})=1$, so $K(d,\bm{v})=K(c,\bm{v})$.
This follows from the definitions \eqref{n10:radicals} and \eqref{n10:K}.
For fixed $c,\bm{v}$,
we have
\begin{equation}\label{eq:fix-cv}
    \sum_{\substack{\mathrm{cube\text{-}free}\ b\sim D/c \\ R_{j+2,k+2}(b,\bm{v})=1}}
|S_b(\bm{v})| \ll_{F,\varepsilon} (DH)^\varepsilon (D/c)^{(n+j+3)/2},
\end{equation}
by \eqref{n10:residual-fixed-point}, since $k\leqslant j+1$.
Consequently the left-hand side $\mathcal L$ of \eqref{n10:weighted-mean} satisfies
\begin{equation}\label{n10:small-radical-allocation}
\mathcal L\ll_{F,\varepsilon} (DH)^\varepsilon D^{(n+j+3)/2}
\sum_{\substack{r\leqslant T\\r\ \mathrm{square\text{-}free}\\\gcd(r,m)=1}}
\sum_{\substack{\operatorname{rad}(c)=r\\c\ \mathrm{cube\text{-}free}\\c\leqslant2D}}
\sum_{\substack{\bm{v}\in(P_j\cap Q_k)\cap\mathcal V\\
R_{j+2,k+2}(c,\bm{v})=r\\K(c,\bm{v})\sim K_j}}
\frac{|S_c(\bm{v})|}{c^{(n+j+3)/2}}.
\end{equation}

Now write $c=d_1d_2^2$, so that $r=d_1d_2$.
By \eqref{EQ:K-relaxed-hybrid-pointwise}, we have
$$\frac{S_c(\bm{v})}{c^{(n+j+3)/2}}
\ll (DH)^\varepsilon d_2^{k-j} K(d_1d_2^2,\bm{v})
= (DH)^\varepsilon d_2^{k-j}
\prod_{p\mid d_1}
p^{\frac{e(\bm{v};p)-j}{2}-1}
\prod_{p\mid d_2}
p^{f(\bm{v};p)-k-2},$$
by \eqref{n10:K}, since $e(\bm{v};p)\geqslant j+2$ and $f(\bm{v};p)\geqslant k+2$.
Put
\[
B_{j,k}=\left(\frac{\delta_{1,2}(j)}{j+1}
+2\delta_0(j)\right) \bm1_{k=j}.
\]
By \eqref{n10:progression-counts} if $k=j$,
and by \eqref{n10:Q-progression-counts_square} if $k=j+1$,
a fixed residue class modulo $r$ contains
$$\ll_{F,\varepsilon} (T/r)^{n-j-2+B_{j,k}+\varepsilon}$$
vectors $\bm{v}\in(P_j\cap Q_k)\cap\mathcal V$.
Moreover, in the light of \eqref{eq:silver},  the Chinese remainder theorem
and the Lang--Weil bound on the varieties $Z_h$ for $j+2\leqslant h\leqslant n-4$,
the number of residues $\bm{v}\bmod{r}$ for which $e(\bm{v};p) = h_p$ for all $p\mid d_1$
and $f(\bm{v};p) = \ell_p$ for all $p\mid d_2$ is
\begin{equation*}
\ll_{F,\varepsilon} r^\varepsilon \prod_{p\mid d_1} p^{n-h_p-\delta_{n-5,n-4}(h_p)}
\prod_{p\mid d_2} p^{n-\ell_p-\delta_{n-5,n-4}(\ell_p)}.
\end{equation*}
When $j=k=0$, since $K(c,\bm{v}) \gg K_j$, it will also be convenient to note that
\begin{equation*}
1 \ll K_j^{-\alpha_n\delta_0(j,k)} K(c,\bm{v})^{\alpha_n\delta_0(j,k)},
\end{equation*}
where $\alpha_n=1/(n-8)$, as in the statement of the lemma.
Plugging the bounds above into \eqref{n10:small-radical-allocation} gives
\begin{equation*}
\mathcal L \ll_{F,\varepsilon} (DH)^\varepsilon D^{(n+j+3)/2} T^{n-j-2+B_{j,k}} K_j^{-\alpha_n\delta_0(j,k)}
\sum_{\substack{d_1d_2\leqslant T\\d_1d_2\ \mathrm{square\text{-}free}\\\gcd(d_1d_2,m)=1}}
\sup_{\substack{j+2\leqslant h_p\leqslant n-4 \\ k+2\leqslant \ell_p\leqslant n-4}}
\prod_{p\mid d_1} p^{a_p}
\prod_{p\mid d_2} p^{b_p},
\end{equation*}
where
\begin{equation*}
\begin{split}
a_p
&= (\tfrac{h_p-j}{2}-1) (1+\alpha_n\delta_0(j,k))
- (n-j-2+B_{j,k})
+ (n-h_p-\delta_{n-5,n-4}(h_p)) \\
&\leqslant (h_p-j-2) (1+\alpha_n\delta_0(j,k))
- (n-j-2+B_{j,k})
+ (n-h_p-\delta_{n-5,n-4}(h_p)) \\
&= (h_p-j-2) \alpha_n\delta_0(j,k)
-B_{j,k}
-\delta_{n-5,n-4}(h_p),
\end{split}
\end{equation*}
since $h_p\geqslant j+2$,
and where
\begin{equation*}
\begin{split}
b_p &= (k-j)
+ (\ell_p-k-2) (1+\alpha_n\delta_0(j,k))
- (n-j-2+B_{j,k})
+ (n-\ell_p-\delta_{n-5,n-4}(\ell_p)) \\
&= (\ell_p-k-2) \alpha_n\delta_0(j,k)
-B_{j,k}
-\delta_{n-5,n-4}(\ell_p).
\end{split}
\end{equation*}

In order to analyse the exponents $a_p$ and $b_p$, let
$$f_{j,k}(h) := (h-j-2) \alpha_n\delta_0(j,k)
-B_{j,k}
-\delta_{n-5,n-4}(h)$$
for $j+2\leqslant h\leqslant n-4$.
Then $a_p\leqslant f_{j,k}(h_p)$ and $b_p\leqslant f_{j,k}(\ell_p)$, since $k\geqslant j$.
If $n-7\leqslant j\leqslant n-6$, then $j\geqslant 3$ and $n-5\leqslant h\leqslant n-4$, so
$B_{j,k}=0$ and $f_{j,k}(h) = -1$, whence $a_p,b_p\leqslant -1$ and
\begin{equation*}
\mathcal L \ll_{F,\varepsilon} (DH)^\varepsilon D^{(n+j+3)/2} T^{n-j-2}
\sum_{d_1d_2\leqslant T} (d_1d_2)^{-1}
\ll_{F,\varepsilon} (DH)^{2\varepsilon} D^{(n+j+3)/2} T^{n-j-2},
\end{equation*}
which is satisfactory since $\delta_0(j,k) = 0$ and $\delta_{n-7,n-6}(j) = 1$.
If $0\leqslant j\leqslant n-8$ and $k\geqslant 1$, then $f_{j,k}(h) \leqslant -B_{j,k}$,
where $0\leqslant B_{j,k}\leqslant 1$, so $a_p,b_p\leqslant -B_{j,k}$ and
\begin{equation*}
\mathcal L \ll_{F,\varepsilon} (DH)^\varepsilon D^{(n+j+3)/2} T^{n-j-2+B_{j,k}}
\sum_{d_1d_2\leqslant T} (d_1d_2)^{-B_{j,k}}
\ll_{F,\varepsilon} (DH)^{2\varepsilon} D^{(n+j+3)/2} T^{n-j-1},
\end{equation*}
which is satisfactory since $\delta_0(j,k) = \delta_{n-7,n-6}(j) = 0$.
Finally, if $j=k=0$, then $B_{j,k}=2$ and
\[
f_{0,0}(h) = \frac{h-2}{n-8}-2-\delta_{n-5,n-4}(h)\leqslant -1
\qquad(2\leqslant h\leqslant n-4).
\]
Indeed, $f_{0,0}(h)$ is maximised either at $h=n-6$, where $f_{0,0}(n-6) = -1$,
or at $h=n-4$, where $f_{0,0}(n-4) = (n-6)/(n-8) - 3 \leqslant -1$
since $n\geqslant 10$.
Thus $a_p,b_p\leqslant -1$ and
\begin{equation*}
\mathcal L \ll_{F,\varepsilon} (DH)^\varepsilon D^{(n+j+3)/2} T^{n-j} K_j^{-\alpha_n}
\sum_{d_1d_2\leqslant T} (d_1d_2)^{-1}
\ll_{F,\varepsilon} (DH)^{2\varepsilon} D^{(n+j+3)/2} T^{n-j} K_j^{-\alpha_n},
\end{equation*}
which is satisfactory since $\delta_0(j,k) = 1$ and $\delta_{n-7,n-6}(j) = 0$.

\label{lem:weight-comp}
Let notation be as in \eqref{n10:average-box}.
Suppose $0\leqslant j\leqslant n-6$ and $k\in \{j,j+1\}$.
Then
\begin{equation}\label{n10:weighted-mean-comp}
\sum_{\substack{
d\sim D\\d\ \mathrm{cube\text{-}free}\\
\gcd(d,m)=1}}
\sum_{\substack{
\bm{v}\in(P_j\cap Q_k)\cap\mathcal V\\
R_{j+2,k+2}(d,\bm{v})\geqslant T}}
|S_d(\bm{v})|\ll_{F,\varepsilon}
(DH)^\varepsilon
\sum_{\ell=j+2}^{n-4}
T^{n-\ell+1-\delta_{n-5,n-4}(\ell)}
D^{\frac{n+\ell+1}{2}}.
\end{equation}

Put $x=T/D^{1/3}$ and let 
$$\mathcal U_d := \{\bm{v}\in\mathcal V\cap P_0\cap Q_0:
R_{2,2}(d,\bm{v})\leqslant T\}.$$
Observe that
\begin{equation*}
\begin{split}
\sum_{\substack{
d\sim D\\
d\ \text{cube-free}\\
\gcd(d,m)=1}}
\sum_{\bm{v}\in\mathcal V}
w(\bm{v})|S_d(\bm{v})|
&=
\sum_{\substack{
d\sim D\\
d\ \text{cube-free}\\
\gcd(d,m)=1}}
\sum_{\bm{v}\in \mathcal U_d}
w(\bm{v})|S_d(\bm{v})|
+
\sum_{\substack{
d\sim D\\
d\ \text{cube-free}\\
\gcd(d,m)=1}}
\sum_{\bm{v}\in \mathcal V \setminus \mathcal U_d}
w(\bm{v})|S_d(\bm{v})|\\
&=M+E,
\end{split}
\end{equation*}
say.
We will prove that $E \ll (DH)^\varepsilon \mathcal R$
and that $M \ll (DH)^\varepsilon D^{13/2}T^{20/3}\|P\|_1^{2/3}\|w\|_1^{1/3}$.

We provide two different bounds for $E$.
First we sort the vector $\bm{v}$ according to its reduction modulo $m$.
If $\bm{v}\equiv \bm{a}\bmod{m}$, then $w(\bm{v}) \leqslant P(\bm{a})$.
Thus
\begin{equation*}
E=\sum_{\substack{\bm{a}\bmod{m}}}\sum_{\substack{
d\sim D\\
d\ \text{cube-free}\\
\gcd(d,m)=1}}
\sum_{\substack{
\bm{v}\in \mathcal V \setminus \mathcal U_d\\
\bm{v}\equiv\bm{a}\bmod{m}}} w(\bm{v})|S_d(\bm{v})|
\leqslant \|P\|_{1}\max_{\substack{\bm{a}\bmod{m}}} f(\bm{a}),
\end{equation*}
where
\[
f(\bm{a}) = \sum_{\substack{
d\sim D\\
d\ \text{cube-free}\\
\gcd(d,m)=1}}
\sum_{\substack{
\bm{v}\in \mathcal V \setminus \mathcal U_d\\
\bm{v}\equiv\bm{a}\bmod{m}}} |S_{d}(\bm{v})|.
\]
At this stage we recall from the 
start of \S\ref{sec:silver} that 
the set $\{P_j\cap Q_k\}_{j,k=0}^{n-4}$
gives a partition of $\mathbb{Q}^n$.
After an application of
Lemma~\ref{LEM:n5divisorbound} for $(j,k)=(n-5,n-5)$,
Lemma~\ref{n10:weighted-conductor} for $(j,k)\ne (0,0),(n-5,n-5)$,
and Lemma~\ref{lem:weight-comp} for $(j,k)\ne (n-5,n-5)$,
one gets
\[
\begin{split}
f(\bm{a}) &\ll (DH)^\varepsilon
\left(
TD^9+T^9D^{13/2}+T^8D^7
+T^7D^{15/2}+T^5D^8+T^4D^{17/2}
\right)\\&\ll(DH)^\varepsilon\left(xD^{28/3}+x^{9}D^{19/2}+x^{8}D^{29/3}+x^{7}D^{59/6}+x^{5}D^{29/3}+x^{4}D^{59/6}\right).
\end{split}
\]
Since $D^{59/6}(x^{4}+x^{7})\leqslant 2D^{59/6}(x+x^{9})$,
it follows that
\[
\begin{split}
f(\bm{a}) &\ll  (DH)^\varepsilon\left(xD^{28/3}+x^{9}D^{19/2}+x^{8}D^{29/3}+x^{5}D^{29/3}+(x+x^{9})D^{59/6}\right)\\&\ll (DH)^\varepsilon D^{59/6}(x+x^{9})
= (DH)^\varepsilon (D^{19/2}T+D^{41/6}T^9),
\end{split}
\]
since $D\gg 1$
and $ x=T/D^{1/3}$.
Second,
thanks to the $h=\ell=n-3$ case of \eqref{n10:residual-fixed-point}
we know that for every $\bm{v}\in P_{j}\cap Q_{k}$, for $j,k\in\{0,\dots,n-5\}$ we have 
\[
\sideset{}{^*}\sum_{d_1\sim D_1}
\sideset{}{^*}\sum_{\substack{
d_2\sim D_2\\\gcd(d_1,d_2)=1}}
|S_{d_1d_2^2}(\bm{v})|\ll_{F,\varepsilon} (DH)^\varepsilon
D^{n-3/2} D_1^{\max\{j-n+6,0\}/2}
\ll (DH)^\varepsilon D^{n-1},
\]
since $j\leqslant n-5$.
Indeed, for $j=k=n-5$
this was already observed in the proof of Lemma~\ref{LEM:n5divisorbound}.
Hence
\[
E\leqslant \sum_{\substack{
\bm{v}\in\mathcal V}} w(\bm{v})\sum_{\substack{
d\sim D\\
d\ \text{cube-free}\\
\gcd(d,m)=1}}
|S_{d}(\bm{v})|
\ll \|w\|_{1} (DH)^\varepsilon D^9.
\]
Combining the two bounds, we conclude that $E\ll (DH)^\varepsilon \mathcal R$.

It remains to bound
\[
M = \sum_{\substack{
d\sim D\\
d\ \text{cube-free}\\
\gcd(d,m)=1}}
\sum_{\substack{
\bm{v}\in\mathcal V\cap P_0\cap Q_0 \\ R_{2,2}(d,\bm{v})\leqslant T}}w(\bm{v})|S_{d}(\bm{v})|.
\]
Let $M(K_0)$ be the contribution to $M$ from $K(d,\bm{v}) \sim K_0$.
We bound $M(K_0)$ using the same two methods as for $E$.
First, the $(j,k)=(0,0)$ case of Lemma~\ref{n10:weighted-conductor} implies that
\begin{equation*}
M(K_0) \ll \|P\|_{1}
(DH)^\varepsilon T^n D^{\frac{n+3}{2}} K_0^{-1/2}.
\end{equation*}
Second, by \eqref{n10:weighted-fixed-point} for $(j,k)=(0,0)$ we have
\begin{equation*}
M(K_0) \ll
\|w\|_{1} (DH)^\varepsilon D^{\frac{n+3}{2}} K_0.
\end{equation*}
Thus
\begin{equation*}
M(K_0)
= M(K_0)^{2/3} M(K_0)^{1/3}
\ll (DH)^\varepsilon D^{\frac{n+3}{2}}
\left(\|P\|_{1} T^n K_0^{-1/2}\right)^{2/3}
\left(\|w\|_{1} K_0\right)^{1/3}.
\end{equation*}
The powers of $K_0$ cancel out,
leading to $M(K_0) \ll (DH)^\varepsilon D^{(n+3)/2}T^{2n/3}\|P\|_1^{2/3}\|w\|_1^{1/3}$.
Dyadic summation over the interval $1/2 \leqslant K_0 \ll D^{O(1)}$ completes the proof.

\label{prop:n10-clean-shifted}
Fix $0<\gamma<1/96$.
There exists a modulus $W$ as in \eqref{large-fixed-W} such that
for every $\varepsilon>0$, $\bm{v}_0\in \mathbb{R}^n$ and $Q,L\geqslant 1/2$, we have
\begin{equation}\label{eq:n10-clean-shifted}
\sum_{q\sim Q}
\sum_{\substack{\bm0\ne\bm{v}\in\mathbb{Z}^{10}\\
|\bm{v}-\bm{v}_0|\leqslant L}}
|S_{q,W}(\bm{v})|
\ll_{F,\gamma,\varepsilon}
(LQ+|\bm{v}_0|)^\varepsilon (L+Q^{1/3})^{10}Q^{20/3-\gamma}.
\end{equation}
Here $W$ may depend on $F$ and $\gamma$, but not on $\bm{v}_0,L,Q,\varepsilon$.

\label{lem:n10-cubefull-weights}
For $0\leqslant\alpha\leqslant10$ and every $\varepsilon>0$,
\[
\sum_{\substack{r\sim C\\r\ \mathrm{cube\text{-}full}}}
\kappa(r)\, (z_1/z_2)^{\alpha/3}
\ll_{\alpha,\varepsilon}
C^{\max(0,(\alpha-9)/12)+\varepsilon}.
\]

\label{p:MV}
Let $Q\geqslant 1$ and $\eta>0$. Then for all $x\in\mathbb{Z}$,
\[
\delta_0(x)=\sum_{q\leqslant Q}
\sum_{\substack{1\leqslant a \leqslant q \\ \gcd(a,q)=1}}
\int_{|\theta|<(qQ)^{-1+\eta}}
p_q(\theta)e((a/q+\theta)x)\mathrm{d}\theta + O_{N,\eta}\left(Q^{-N\eta}\right),
\]
where
$p_q$ is a smooth function satisfying 
$|p_q(\theta)|\ll 1$
and
\begin{equation}\label{eq:MV-kernel-estimate}
 p_q(\theta)=1+O_N\bigl((1+Q^2|\theta|)^{2N+2}(q/Q)^N\bigr)
 \qquad(\theta\in\mathbb{R}).
\end{equation}

Let $F_1 = \partial F/\partial x_1$.
Writing $\bm{x}=P\bm{y}$ in \eqref{eq:defIq} gives
$I(\theta;\bm0)=P^n J_w(P^3\theta)$, where
\begin{equation*}
J_w(t) = \int_{\mathbb{R}^n} w(\bm{y})e(tF(\bm{y}))\,\mathrm{d}\bm{y}
= \int_{\mathbb{R}^n} w(\bm{y})e(tf)\,\frac{\mathrm{d} f}{|F_1(\bm{y})|} \mathrm{d}\bm{y}'
\end{equation*}
by the change of coordinates $\bm{y}\mapsto (f,\bm{y}')$
where $f = F(\bm{y})$ and $\bm{y}' = (y_2,\dots,y_n)$,
which is valid by \eqref{eq:smoothsub}.
In particular, $J_w$ is Schwartz in $t$, by integration by parts over $f$.
By Fourier inversion,
\begin{equation*}
\int_{\mathbb{R}} J_w(t) \,\mathrm{d} t = \int_{F(\bm{y})=0} w(\bm{y})\,\frac{\mathrm{d}\bm{y}'}{|F_1(\bm{y})|} > 0,
\end{equation*}
since $w\geqslant 0$, $w(\bm{x}_0)>0$ and $F(\bm{x}_0) = 0$.

Now write $\theta = t/P^3$ in the definition of $M(P)$ to get
\begin{equation*}
\frac{M(P)}{P^{n-3}}
= \sum_{q\leqslant Q}\frac{S_{q,W}(\bm{0})}{\operatorname{lcm}(q,W)^n}
\int_{|t/P^3|<(qQ)^{-1+\eta}} p_q(t/P^3)
J_w(t)\mathrm{d} t.
\end{equation*}
Let $B_q = P^3 (qQ)^{-1+\eta} \geqslant P^3 (qQ)^{-1} = Q/q$.
By the triangle inequality,
\begin{align*}
\left|\int_{|t|<B_q}p_q(t/P^3)J_w(t)\,\mathrm{d} t-\int_{\mathbb{R}} J_w(t) \,\mathrm{d} t\right|
&\leqslant\int_{|t|<B_q}|p_q(t/P^3)-1|\,|J_w(t)|\,\mathrm{d} t
+\int_{|t|\geqslant B_q}|J_w(t)|\,\mathrm{d} t\\
&\ll_w \frac qQ\int_{\mathbb{R}}(1+|t|)^4|J_w(t)|\,\mathrm{d} t+B_q^{-1}
\ll_{F,w}\frac qQ,
\end{align*}
where we have applied the $N=1$ case of \eqref{eq:MV-kernel-estimate},
together with the rapid decay of $J_w$.
Consequently, by the triangle inequality
and the absolute convergence of $\mathfrak S_\Omega$
from Lemma~\ref{LEM:localised-singular-series-convergence},
\begin{align*}
\frac{M(P)}{P^{n-3}}-\mathfrak S_\Omega \int_{\mathbb{R}} J_w(t) \,\mathrm{d} t
&\ll_{F,w}\sum_{q\leqslant Q}\frac{|S_{q,W}(\bm{0})|}{\operatorname{lcm}(q,W)^n} \frac qQ
+\sum_{q>Q} \frac{|S_{q,W}(\bm{0})|}{\operatorname{lcm}(q,W)^n} \int_{\mathbb{R}} J_w(t) \,\mathrm{d} t \\
& \ll Q^{-1/2} \sum_{q\geqslant 1} \frac{|S_{q,W}(\bm{0})|}{\operatorname{lcm}(q,W)^n}
+ \sum_{q>Q^{1/2}} \frac{|S_{q,W}(\bm{0})|}{\operatorname{lcm}(q,W)^n} = o(1)
\end{align*}
as $P\to \infty$.
Thus $M(P)/P^{n-3} \to \mathfrak S_\Omega \int_{\mathbb{R}} J_w(t) \,\mathrm{d} t > 0$,
as $P\to \infty$, where the positivity of $\mathfrak{S}_\Omega$ is a consequence of Lemma~\ref{LEM:localised-singular-series-convergence}.

We may assume that $\theta \neq 0$, since $\phi>0$.
Write $\bm{x}=P\bm{y}$.
As $F$ is cubic, we have
$\nabla F(P\bm{y})=P^2\nabla F(\bm{y})$ and the volume in question is
\[
P^n\operatorname{Vol}\left\{
\bm{y}\in\mathbb{R}^n:
|\bm{y}-\bm{x}_0|\leqslant 2\ell,\;
|q\theta P^2\nabla F(\bm{y})-\bm{v}|\leqslant P^\varepsilon V_0
\right\}.
\]
By \eqref{eq:diffU}, the box $|\bm{y}-\bm{x}_0|\leqslant 2\ell$ is contained in $U$.
Using the diffeomorphism
$$\bm{y}\mapsto (\Psi(\bm{y}),y_{\rho+1},\dots,y_n)$$
on $U$ and the Jacobian bound \eqref{eq:smoothsub''},
where $\Psi$ was defined in \eqref{eq:Psi},
we find by Fubini's theorem that
\[
\operatorname{Vol}\{\bm{y}\in U:|\Psi(\bm{y})-\bm{a}|\leqslant \Delta\}
\ll \Delta^\rho ,
\]
uniformly for $\bm{a}\in\mathbb{R}^\rho$ and $0<\Delta\leqslant 1$.
For $\Delta>1$ we take the trivial bound $O(1)$ for the volume. 
It follows that
\begin{equation}
\label{preslop}
\operatorname{Vol}\left\{
\bm{y}\in\mathbb{R}^n:
|\bm{y}-\bm{x}_0|\leqslant 2\ell,\;
|\nabla F(\bm{y})-\bm{b}|\leqslant \Delta
\right\}
\ll \min\{1,\Delta^\rho\},
\end{equation}
uniformly 
for $\bm{b}\in\mathbb{R}^n$.


Applying this with $\bm{b}=(q\theta P^2)^{-1}\bm{v}$ and 
$\Delta= (q|\theta|P^2 )^{-1}P^\varepsilon V_0$, we deduce that 
\begin{equation*}
\operatorname{Vol}\left\{
\bm{x}\in\mathbb{R}^n:
|\bm{x}/P-\bm{x}_0|\leqslant 2\ell,\;
|q\theta\nabla F(\bm{x})-\bm{v}|\leqslant P^\varepsilon V_0
\right\}
\ll 
P^{n+O_n(\varepsilon)}
\min\left\{
1,
\frac{ V_0}{R\phi P^2}
\right\}^\rho,
\end{equation*}
since $q\asymp_W R$ and $|\theta|\sim\phi$. The lemma will follow if we are able to show that 
$$
\min\left\{
1,
\frac{ V_0}{R\phi P^2}\right\}
\ll \frac{R}{PV_0},
$$
where we recall that $V_0$ is given by \eqref{eq:V}. 
But this is easily checked on a case distinction between 
the case  $\phi P^3\leqslant 1$ (so that $V_0=RP^{-1}$) and the case
 $\phi P^3>1$ (so that $V_0=RP^{-1}\sqrt{\phi P^3}$).

\label{lem:gradient-volume2}
Let $q\asymp_W R$, $|\theta|\sim \phi$, and let $V, V_0$ be given by \eqref{eq:V}.
Then, for every $\varepsilon>0$,
we have
\[
\sum_{\substack{\bm{v}\in \mathbb{Z}^n\\ 
|\bm{v}|\leqslant P^\varepsilon V}}
\operatorname{Vol}\left\{
\bm{x}\in\mathbb{R}^n:
|\bm{x}/P-\bm{x}_0|\leqslant 2\ell,\;
|q\theta\nabla F(\bm{x})-\bm{v}|\leqslant P^\varepsilon V_0
\right\}
\ll
P^{n+O_n(\varepsilon)}(1+V_0)^n.
\]

\label{aislop}
Fix $\varepsilon>0$.
Let $P,R\geqslant 1/2$ and $\phi>0$.
Let $V,V_0$ be given by \eqref{eq:V}.
Assume that \eqref{eq:diffU} holds.
Let $\rho=r(F)$.
Let $L\geqslant 0$ be a real number.
If $|\alpha| \asymp_W R\phi$, then
\begin{equation*}
\sum_{\bm{v}\in \mathbb{Z}^n}
M_\alpha(\bm{v},L) \ll
\begin{cases}       
0 &\text{ if $P^\varepsilon V < 1$,}\\
P^{n+O_n(\varepsilon)} (1+\tfrac{L}{V})^\rho (1+V_0+L)^{n-\rho} V_0^\rho & \text{ if $\phi P^3>1$},\\
P^{n+O_n(\varepsilon)} (V+L)^n & \text{ if $\phi P^3\leqslant 1$},
\end{cases}
\end{equation*}
where
\begin{equation*}
M_\alpha(\bm{v},L) := \sup_{\substack{\bm{a}\in \mathbb{Z}^n\\ 
0<|\bm{a}|\leqslant P^\varepsilon V\\
|\bm{a}-\bm{v}| \leqslant L}}
\operatorname{Vol}\left\{
\bm{x}\in\mathbb{R}^n:
|\bm{x}/P-\bm{x}_0|\leqslant 2\ell,\;
|\alpha\nabla F(\bm{x})-\bm{a}|\leqslant P^\varepsilon V_0
\right\},
\end{equation*}
with the convention that $\sup_{\emptyset} = 0$
if the set in the supremum is empty.

\label{conj:clean-shifted}
Fix $n\geqslant 10$.
There exists a constant $b < 2n/3$ such that
for all real $\varepsilon>0$,
$B,L,R\geqslant 1/2$,
and vectors $\bm{v}\in \mathbb{Z}^n$ with $|\bm{v}|\leqslant B$,
we have
\begin{equation*}
\sum_{q\sim R} 
\sum_{\substack{\bm{0}\ne \bm{a}\in \mathbb{Z}^n\\ 
|\bm{a}-\bm{v}| \leqslant L}} |S_{q,W}(\bm{a})|
\ll_\varepsilon (BLR)^\varepsilon (L + R^{1/3})^n R^b.
\end{equation*}

\label{prop:remove-integral}
Assume Conjecture~\ref{conj:clean-shifted} for some fixed $n\geqslant 10$.
Let $\rho=r(F)$.
Then
\begin{equation*}
E(P;R,\phi) \ll \min\{1,\phi P^3\} \left(1 + P^{n-3+O(\eta+\varepsilon)-\Delta}\right),
\end{equation*}
where $\Delta = \min(\rho/4-3/2, \rho/2-1, 2n/3-b) > 0$ is admissible.

Plugging Lemma~\ref{aislop} with $\alpha = R\tau$
and Conjecture~\ref{conj:clean-shifted} with $B \ll P^{100}$
into \eqref{eq:bislop},
the desired bound is trivial unless
$P^\varepsilon V\geqslant 1$,
in which case
\begin{equation*}
E(P;R,\phi) \ll \phi + (1 + \tfrac{R^{1/3}}{L})^n \phi R^{b-n} P^{n+O_n(\varepsilon)}
\begin{cases}       
(1+\tfrac{L}{V})^\rho (V_0+L)^{n-\rho} V_0^\rho & \text{ if $\phi P^3>1$},\\
(V+L)^n & \text{ if $\phi P^3\leqslant 1$},
\end{cases}
\end{equation*}
for any real $1\leqslant L\ll P^{100}$,
since $L\asymp \lceil{L}\rceil\in \mathbb{Z}$.
Here $1/2\leqslant R\ll P^{3/2}$ and $\phi \ll (RP^{3/2})^{-1+\eta}$.

If $\phi P^3\leqslant 1$ then $V=RP^{-1}$ and $P^\varepsilon V\gg 1$,
so $R^{1/3} \gg R/P = V \gg P^{-\varepsilon}$, since $R\ll P^{3/2}$.
Taking $L \asymp R^{1/3} \gg V$ gives
\begin{equation*}
E(P;R,\phi) \ll \phi + \phi R^{b - 2n/3} P^{n+O_n(\varepsilon)}
\ll \phi + \phi P^{b - 2n/3} P^{n+O(\varepsilon)},
\end{equation*}
since $R\gg P^{1-\varepsilon}$.
Thus $\Delta = 2n/3 - b > 0$ is admissible in this case.

Now suppose $\phi P^3>1$.
Then $V=R\phi P^2$ and
$V_0=R\phi^{1/2}P^{1/2}$,
with $P^\varepsilon V\gg 1$,
$V>V_0$
and $V_0 \ll (RP^{3/2})^{\eta/2} R^{1/2} P^{-1/4} \ll (RP^{3/2})^{\eta/2} R^{1/3}$.
Taking $L \asymp R^{1/3}$ gives
\begin{equation*}
E(P;R,\phi) \ll 1 + \phi R^{b-n} P^{n+O_n(\varepsilon)}  
(1+\tfrac{R^{1/3}}{V})^\rho (V_0+R^{1/3})^{n-\rho} V_0^\rho.
\end{equation*}
Writing $V = (\phi P^3)^{1/2}V_0$ and $V_0+R^{1/3} \ll (RP^{3/2})^{\eta/2} R^{1/3}$, this is
\begin{equation*}
\ll 1 + \phi R^{b-2n/3-\rho/3} P^{n+O(\eta+\varepsilon)}  
(V_0+\tfrac{R^{1/3}}{(\phi P^3)^{1/2}})^\rho.
\end{equation*}
Since $\rho\geqslant 2$, optimising over the interval $\max(P^{-3}, R^{-1} P^{-2-\varepsilon})
\ll \phi \ll (RP^{3/2})^{-1+\eta}$ gives
\begin{equation*}
\begin{split}
E(P;R,\phi) &\ll 1 + R^{b-2n/3-\rho/3} P^{n+O(\eta+\varepsilon)}  
(R^{-1}P^{-3/2} R^{\rho/2}P^{-\rho/4} + P^{-3} \max(1, P/R)^{1 - \rho/2} R^{\rho/3}) \\
&= 1 + R^{b-2n/3} P^{n-3+O(\eta+\varepsilon)}  
((R/P^{3/2})^{\rho/6 - 1} + \max(1, P/R)^{1 - \rho/2}).
\end{split}
\end{equation*}
By writing each term on the right-hand side as
$P$ raised to a piecewise linear function of the quantity $\log_P R$,
we find that this is optimised at either $R\asymp 1$, $R\asymp P$, or $R\asymp P^{3/2}$.
Thus
\begin{equation*}
E(P;R,\phi) \ll 1 + P^{n-3+O(\eta+\varepsilon)}  
((1/P^{3/2})^{\rho/6 - 1} + P^{1 - \rho/2} + P^{b-2n/3}).
\end{equation*}
Since $\rho = r(F)\geqslant \lceil 2n/3\rceil \geqslant 7$,
the saving $\Delta = \min(\rho/4-3/2, \rho/2-1, 2n/3-b) > 0$ is admissible.

\label{n10:ss}
There exist an integer $N\geqslant1$ and closed subschemes
\[
\operatorname{\mathbb{A}}^n_\mathbb{Z}=\mathcal Z_0\supset \mathcal Z_1\supset\cdots\supset \mathcal Z_n=\{\bm0\}
\]
defined by homogeneous polynomials such that the following hold:
\begin{enumerate}
\item \label{item:strat-geom-dim-bound}
We have $\dim (\mathcal Z_i \otimes \mathbb{Q}) \leqslant n-i$ for every $0\leqslant i\leqslant n$.

\item \label{item:strat-fourier-bound}
For every finite field $\mathbb{F}_q$
of characteristic $p\nmid N$, every $0\leqslant i\leqslant n-1$, and every
vector $\bm{v}\in \mathbb{F}_q^n \setminus \mathcal Z_{i+1}(\mathbb{F}_q)$, we have
\begin{equation}\label{eq:main-bound}
T_q(\bm{v})\ll_{n,d} q^{(n-1+i)/2}.
\end{equation}

\item If $\mathcal X \otimes \mathbb{Q}$ is geometrically integral
and $d\geqslant 2$, then for every $0\leqslant i\leqslant n-1$, we have
\begin{equation}
\label{EQ:nice-sandwich}
\widehat W_i \subset \mathcal Z_{i+1} \otimes \mathbb{Q} \subset \widehat B_i,
\end{equation}
in the notation of \eqref{EQ:general-bad-hyperplanes}
and \eqref{EQ:general-large-gauss-fibres}.

\item Let $\overline{\mathcal Z_i(\mathbb{Q})}$ denote the Zariski closure of
$\mathcal Z_i(\mathbb{Q})$ in the variety $\mathcal Z_i \otimes \mathbb{Q}$.
If $\mathcal X(\mathbb{Q})=\emptyset$, then for every $1\leqslant i\leqslant n-1$, we have
\begin{equation}\label{eq:rational-main}
\dim \overline{\mathcal Z_i(\mathbb{Q})}
\leqslant n-i-1.
\end{equation}
\end{enumerate}

\label{app:ss:lem:homogeneity}
For every $\bm{v}\neq\bm0$, with $h=[\bm{v}]$, one has
\begin{equation*}
 T_q(\bm{v})=1+q\#X_h(k)-\#X(k).
\end{equation*}

\label{app:ss:def:Yi}
For $1\leqslant i\leqslant n$, define
\begin{equation}\label{app:ss:eq:Yi}
 Y_i=\{h\in P^\vee:\dim\Sigma_{\overline h}\geqslant i-1\},
\end{equation}
where $\overline h$ is a geometric point over $h$.

\label{app:ss:lem:dimension}
The loci $Y_i$ satisfy $\operatorname{codim}_{P^\vee}Y_i\geqslant i$.
In particular $Y_n=\emptyset$.

\label{app:ss:prop:global}
The schemes $\mathcal Z_i$ satisfy (\ref{item:strat-geom-dim-bound})
and (\ref{item:strat-fourier-bound}) of Theorem~\ref{n10:ss}.

\label{app:ss:prop:rational-projective}
Assume $X(\mathbb{Q})=\emptyset$. For the generic-fibre loci
$Y_i=(\mathcal Y_i)_\mathbb{Q}$ and $1\leqslant i\leqslant n-1$,
\begin{equation*}
 \operatorname{codim}_{P^\vee_\mathbb{Q}}\overline{Y_i(\mathbb{Q})}\geqslant i+1.
\end{equation*}
